struct ReaderOutput {
    head: Vec<u8>,
    total: u64,
}

struct Supervised {
    child: Option<std::process::Child>,
    pgid: u32,
    reader_handle: Option<std::thread::JoinHandle<()>>,
    rx: std::sync::mpsc::Receiver<ReaderOutput>,
}

impl Drop for Supervised {
    fn drop(&mut self) {
        if self.child.is_none() && self.reader_handle.is_none() {
            return;
        }
        #[cfg(unix)]
        unsafe {
            let _ = killpg(self.pgid as i32, 9);
            let _ = kill(self.pgid as i32, 9);
            let _ = kill(-(self.pgid as i32), 9);
        }
        if let Some(mut c) = self.child.take() {
            let _ = c.kill();
            let _ = c.wait();
        }
        if let Some(h) = self.reader_handle.take() {
            let _ = h.join();
        }
    }
}

fn reader_main(
    stdout_opt: Option<std::process::ChildStdout>,
    head_limit: usize,
    tx: std::sync::mpsc::Sender<ReaderOutput>,
) {
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    if let Some(mut out) = stdout_opt {
        let mut buf = [0u8; 8192];
        loop {
            match out.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    total = total.saturating_add(n as u64);
                    if head.len() < head_limit {
                        let remain = head_limit - head.len();
                        let take = if n < remain { n } else { remain };
                        head.extend_from_slice(&buf[..take]);
                    }
                }
                Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            }
        }
    }
    let _ = tx.send(ReaderOutput { head, total });
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    unsafe {
        use std::os::unix::process::CommandExt;
        cmd.pre_exec(|| {
            unsafe {
                let _ = setsid();
                let _ = setpgid(0, 0);
            }
            Ok(())
        });
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pgid = child.id();
    let stdout_opt = child.stdout.take();
    let (tx, rx) = std::sync::mpsc::channel::<ReaderOutput>();
    let head_limit_for_reader = head_limit;
    let reader_handle = std::thread::spawn(move || {
        reader_main(stdout_opt, head_limit_for_reader, tx);
    });
    let mut sup = Supervised {
        child: Some(child),
        pgid,
        reader_handle: Some(reader_handle),
        rx,
    };
    let start = std::time::Instant::now();
    let mut child_exited = false;
    let mut reader_out: Option<ReaderOutput> = None;
    loop {
        if reader_out.is_none() {
            match sup.rx.try_recv() {
                Ok(o) => {
                    reader_out = Some(o);
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    reader_out = Some(ReaderOutput {
                        head: Vec::new(),
                        total: 0,
                    });
                }
            }
        }
        if !child_exited {
            if let Some(c) = sup.child.as_mut() {
                match c.try_wait() {
                    Ok(Some(_)) => {
                        child_exited = true;
                    }
                    Ok(None) => {}
                    Err(_) => {}
                }
            } else {
                child_exited = true;
            }
        }
        if child_exited && reader_out.is_some() {
            break;
        }
        if start.elapsed() >= deadline {
            #[cfg(unix)]
            unsafe {
                let _ = killpg(sup.pgid as i32, 9);
                let _ = kill(sup.pgid as i32, 9);
                let _ = kill(-(sup.pgid as i32), 9);
            }
            if let Some(mut c) = sup.child.take() {
                let _ = c.kill();
                let _ = c.wait();
            }
            if let Some(h) = sup.reader_handle.take() {
                let _ = h.join();
            }
            return Err(CaptureError::Deadline);
        }
        lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
    }
    let out = reader_out.unwrap();
    if let Some(h) = sup.reader_handle.take() {
        let _ = h.join();
    }
    let _ = sup.child.take();
    let truncated = out.total > head_limit as u64;
    Ok(CaptureResult::new(out.head, out.total, truncated))
}

