fn kill_group_blocking(pgid: u32) {
    #[cfg(unix)]
    {
        let arg = format!(
            "kill -KILL -{} 2>/dev/null; kill -KILL {} 2>/dev/null",
            pgid, pgid
        );
        if let Ok(mut c) = std::process::Command::new("sh")
            .arg("-c")
            .arg(arg)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
        {
            let _ = c.wait();
        }
    }
    #[cfg(not(unix))]
    {
        let _ = pgid;
    }
}

struct Guard {
    child: Option<std::process::Child>,
    pgid: u32,
    reader: Option<std::thread::JoinHandle<(Vec<u8>, u64)>>,
}

impl Drop for Guard {
    fn drop(&mut self) {
        if self.child.is_none() && self.reader.is_none() {
            return;
        }
        for _ in 0..20 {
            kill_group_blocking(self.pgid);
            if let Some(c) = self.child.as_mut() {
                let _ = c.kill();
            }
            let child_done = match self.child.as_mut() {
                Some(c) => match c.try_wait() {
                    Ok(Some(_)) => true,
                    Ok(None) => false,
                    Err(_) => true,
                },
                None => true,
            };
            let reader_done = match self.reader.as_ref() {
                Some(h) => h.is_finished(),
                None => true,
            };
            if child_done && reader_done {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(50));
        }
        if let Some(mut c) = self.child.take() {
            let _ = c.wait();
        }
        if let Some(h) = self.reader.take() {
            let _ = h.join();
        }
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pgid = child.id();
    let stdout = match child.stdout.take() {
        Some(s) => s,
        None => {
            let _ = child.kill();
            let _ = child.wait();
            return Err(CaptureError::Cancelled);
        }
    };
    let reader_handle = std::thread::spawn(move || {
        let mut out = stdout;
        let mut head: Vec<u8> = Vec::new();
        if head_limit > 0 && head_limit < 8192 {
            head.reserve(head_limit);
        } else if head_limit >= 8192 {
            head.reserve(8192);
        }
        let mut total: u64 = 0;
        let mut buf = [0u8; 8192];
        loop {
            let n = match std::io::Read::read(&mut out, &mut buf) {
                Ok(0) => break,
                Ok(n) => n,
                Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            };
            total = total.wrapping_add(n as u64);
            if head.len() < head_limit {
                let need = head_limit - head.len();
                let take = if need < n { need } else { n };
                head.extend_from_slice(&buf[..take]);
            }
        }
        (head, total)
    });

    let mut guard = Guard {
        child: Some(child),
        pgid,
        reader: Some(reader_handle),
    };

    let start = std::time::Instant::now();
    let mut status_opt: Option<std::process::ExitStatus> = None;
    let mut killed_after_exit = false;
    let mut since_kill: u32 = 0;

    loop {
        if status_opt.is_none() {
            if let Some(c) = guard.child.as_mut() {
                match c.try_wait() {
                    Ok(Some(st)) => {
                        status_opt = Some(st);
                    }
                    Ok(None) => {}
                    Err(_) => {
                        return Err(CaptureError::Cancelled);
                    }
                }
            } else {
                return Err(CaptureError::Cancelled);
            }
        }
        if status_opt.is_none() {
            if start.elapsed() >= deadline {
                return Err(CaptureError::Deadline);
            }
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
        } else {
            if !killed_after_exit {
                killed_after_exit = true;
                since_kill = 0;
                kill_group_blocking(pgid);
                if let Some(c) = guard.child.as_mut() {
                    let _ = c.kill();
                }
            } else {
                since_kill += 1;
                if since_kill >= 50 {
                    since_kill = 0;
                    kill_group_blocking(pgid);
                    if let Some(c) = guard.child.as_mut() {
                        let _ = c.kill();
                    }
                }
            }
            let finished = guard
                .reader
                .as_ref()
                .map(|h| h.is_finished())
                .unwrap_or(true);
            if finished {
                break;
            }
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(1)).await;
        }
    }

    let status = match status_opt {
        Some(s) => s,
        None => return Err(CaptureError::Cancelled),
    };
    #[cfg(unix)]
    {
        use std::os::unix::process::ExitStatusExt;
        if status.signal().is_some() {
            return Err(CaptureError::Cancelled);
        }
    }
    let handle_opt = guard.reader.take();
    let (head, total) = match handle_opt {
        Some(h) => match h.join() {
            Ok(v) => v,
            Err(_) => return Err(CaptureError::Cancelled),
        },
        None => return Err(CaptureError::Cancelled),
    };
    let _ = guard.child.take();
    let truncated = total > head_limit as u64;
    Ok(CaptureResult::new(head, total, truncated))
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target = format!("applied:{key}");

    let _ = std::fs::create_dir_all(&effect_dir);

    let already: bool = match std::fs::read_to_string(&log_path) {
        Ok(content) => content.lines().any(|l| l == target),
        Err(_) => false,
    };

    let did_append: bool = if already {
        false
    } else {
        {
            use std::io::Write;
            let mut f = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log_path)
                .unwrap();
            f.write_all(format!("{target}\n").as_bytes()).unwrap();
            let _ = f.sync_all();
        }
        true
    };

    if release_path.exists() {
        if did_append {
            return Ok(format!("applied:{key}"));
        } else {
            return Ok(format!("recovered:{key}"));
        }
    }

    let wait = async {
        loop {
            if release_path.exists() {
                break;
            }
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(5)).await;
        }
    };

    match lgwks_bot::rt::time::timeout(deadline, wait).await {
        Ok(()) => {
            if did_append {
                Ok(format!("applied:{key}"))
            } else {
                Ok(format!("recovered:{key}"))
            }
        }
        Err(_) => Err(RecoverError::Deadline),
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let target = format!("applied:{key}");
    let full_line = format!("applied:{key}\n");
    let target_bytes = target.as_bytes();
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    let did_append: bool = {
        let _ = std::fs::create_dir_all(&effect_dir);
        let existing: Vec<u8> = match std::fs::read(&log_path) {
            Ok(v) => v,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
            Err(_) => {
                let _ = std::fs::create_dir_all(&effect_dir);
                match std::fs::read(&log_path) {
                    Ok(v) => v,
                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
                    Err(e) => panic!("read applied.log: {e:?}"),
                }
            }
        };

        let mut found = false;
        {
            let mut start: usize = 0;
            let mut i: usize = 0;
            while i < existing.len() {
                if existing[i] == b'\n' {
                    if &existing[start..i] == target_bytes {
                        found = true;
                        break;
                    }
                    start = i + 1;
                }
                i += 1;
            }
        }

        if found {
            false
        } else {
            if !existing.is_empty() && existing[existing.len() - 1] != b'\n' {
                let mut trunc_len: u64 = 0;
                let mut idx: usize = 0;
                while idx < existing.len() {
                    if existing[idx] == b'\n' {
                        trunc_len = (idx + 1) as u64;
                    }
                    idx += 1;
                }
                if let Ok(f) = std::fs::OpenOptions::new().write(true).open(&log_path) {
                    let _ = f.set_len(trunc_len);
                    let _ = f.sync_all();
                }
            }

            let mut f = match std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log_path)
            {
                Ok(f) => f,
                Err(_) => {
                    let _ = std::fs::create_dir_all(&effect_dir);
                    std::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(&log_path)
                        .expect("open applied.log")
                }
            };
            std::io::Write::write_all(&mut f, full_line.as_bytes())
                .expect("write applied.log");
            let _ = std::io::Write::flush(&mut f);
            let _ = f.sync_all();
            true
        }
    };

    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline
            .checked_sub(start.elapsed())
            .unwrap_or(std::time::Duration::ZERO);
        let step = std::time::Duration::from_millis(5);
        let wait = if remaining < step { remaining } else { step };
        if wait.is_zero() {
            if release_path.exists() {
                break;
            }
            return Err(RecoverError::Deadline);
        }
        lgwks_bot::rt::time::sleep(wait).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

