struct Guard {
    pgid: i32,
    exited: Arc<AtomicBool>,
}

impl Guard {
    fn kill_group(&self) {
        #[cfg(unix)]
        {
            if self.exited.load(Ordering::SeqCst) {
                return;
            }
            if self.pgid <= 0 {
                return;
            }
            unsafe {
                let _ = kill(-self.pgid, 9);
            }
        }
        #[cfg(not(unix))]
        {
            let _ = (&self.pgid, &self.exited);
        }
    }
}

impl Drop for Guard {
    fn drop(&mut self) {
        self.kill_group();
    }
}

async fn sleep_async(dur: std::time::Duration) {
    if dur.is_zero() {
        return;
    }
    let target = std::time::Instant::now() + dur;
    std::future::poll_fn(move |cx| {
        if std::time::Instant::now() >= target {
            Poll::Ready(())
        } else {
            let w = cx.waker().clone();
            let rem = target.saturating_duration_since(std::time::Instant::now());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                w.wake();
            });
            Poll::Pending
        }
    })
    .await
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(std::process::Stdio::null());
    cmd.stdout(std::process::Stdio::piped());
    cmd.stderr(std::process::Stdio::null());
