    {
        use std::os::unix::process::CommandExt;
        unsafe {
            cmd.pre_exec(|| {
                unsafe {
                    setpgid(0, 0);
                }
                Ok(())
            });
        }
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    #[cfg(unix)]
    {
        let pid = child.id() as i32;
        unsafe {
            let _ = setpgid(pid, pid);
        }
    }
    let pgid = child.id() as i32;
    let stdout_opt = child.stdout.take();
    let exited = Arc::new(AtomicBool::new(false));
    let exited_thread = exited.clone();
    let (tx, rx) = std::sync::mpsc::channel::<(Vec<u8>, u64)>();
    let handle = std::thread::spawn(move || {
        let mut head_vec: Vec<u8> =
            Vec::with_capacity(std::cmp::min(head_limit, 8192));
        let mut total: u64 = 0;
        if let Some(mut out) = stdout_opt {
            let mut buf = [0u8; 8192];
            loop {
                match out.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        total = total.saturating_add(n as u64);
                        if head_vec.len() < head_limit {
                            let remain = head_limit - head_vec.len();
                            let take = std::cmp::min(remain, n);
                            head_vec.extend_from_slice(&buf[..take]);
                        }
                    }
                    Err(e)
                        if e.kind() == std::io::ErrorKind::Interrupted =>
                    {
                        continue
                    }
                    Err(_) => break,
                }
            }
        }
        let _ = child.wait();
        exited_thread.store(true, Ordering::SeqCst);
        let _ = tx.send((head_vec, total));
    });
    let guard = Guard { pgid, exited };
    let deadline_instant = std::time::Instant::now() + deadline;
    loop {
        match rx.try_recv() {
            Ok((h, t)) => {
                let truncated = t > head_limit as u64;
                let _ = handle.join();
                let _ = &guard;
                return Ok(CaptureResult::new(h, t, truncated));
            }
