                let _ = handle.join();
                let _ = &guard;
                return Ok(CaptureResult::new(Vec::new(), 0, false));
            }
            Err(std::sync::mpsc::TryRecvError::Empty) => {}
        }
        if std::time::Instant::now() >= deadline_instant {
            guard.kill_group();
            let _ = handle.join();
            return Err(CaptureError::Deadline);
        }
        let remaining =
            deadline_instant.saturating_duration_since(std::time::Instant::now());
        let step =
            std::cmp::min(remaining, std::time::Duration::from_millis(5));
        if step.is_zero() {
            guard.kill_group();
            let _ = handle.join();
            return Err(CaptureError::Deadline);
        }
        sleep_async(step).await;
    }
}

