fn kill_once(pid: u32) {
    let arg = format!("-{}", pid);
    let _ = Command::new("/bin/kill")
        .arg("-KILL")
        .arg(&arg)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    let _ = Command::new("/usr/bin/kill")
        .arg("-KILL")
        .arg(&arg)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    let _ = Command::new("kill")
        .arg("-KILL")
        .arg(&arg)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    let pid_s = format!("{}", pid);
    let _ = Command::new("/usr/bin/pkill")
        .arg("-KILL")
        .arg("-g")
        .arg(&pid_s)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
    let _ = Command::new("pkill")
        .arg("-KILL")
        .arg("-g")
        .arg(&pid_s)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
}

fn group_exists(pid: u32) -> bool {
    let arg = format!("-{}", pid);
    for prog in ["/bin/kill", "/usr/bin/kill", "kill"] {
        match Command::new(prog)
            .arg("-0")
            .arg(&arg)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
        {
            Ok(st) => {
                return st.success();
            }
            Err(_) => continue,
        }
    }
    false
}

fn shutdown_group(pid: u32) {
    for _ in 0..100 {
        kill_once(pid);
        if !group_exists(pid) {
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    kill_once(pid);
}

async fn tiny_sleep(d: Duration) {
    let start = Instant::now();
    std::future::poll_fn(move |cx| {
        if start.elapsed() >= d {
            return Poll::Ready(());
        }
        let rem = d.saturating_sub(start.elapsed());
        let w = cx.waker().clone();
        let _ = std::thread::spawn(move || {
            std::thread::sleep(rem);
            w.wake();
        });
        Poll::Pending
    })
    .await
}

struct Guard {
    pid: u32,
    child: Option<Child>,
    handle: Option<std::thread::JoinHandle<()>>,
    armed: bool,
}

impl Drop for Guard {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        shutdown_group(self.pid);
        if let Some(mut c) = self.child.take() {
            let _ = c.wait();
        }
        kill_once(self.pid);
        if let Some(h) = self.handle.take() {
            let _ = h.join();
        }
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    #[cfg(unix)]
    use std::os::unix::process::CommandExt;
    let mut cmd = Command::new(&argv[0]);
    if argv.len() > 1 {
        cmd.args(&argv[1..]);
    }
    cmd.stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    #[cfg(unix)]
    {
        cmd.process_group(0);
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pid = child.id();
    let stdout = child.stdout.take();
    let lim = head_limit;
    let (tx, rx) = std::sync::mpsc::channel::<(Vec<u8>, u64)>();
    let handle = std::thread::spawn(move || {
        let mut total: u64 = 0;
        let mut head: Vec<u8> = Vec::new();
        if let Some(mut out) = stdout {
            let mut buf = [0u8; 8192];
            loop {
                match out.read(&mut buf) {
                    Ok(0) => break,
                    Ok(n) => {
                        total += n as u64;
                        if head.len() < lim {
                            let want = std::cmp::min(n, lim - head.len());
                            head.extend_from_slice(&buf[..want]);
                        }
                    }
                    Err(_) => break,
                }
            }
        }
        let _ = tx.send((head, total));
    });
    let mut guard = Guard {
        pid,
        child: Some(child),
        handle: Some(handle),
        armed: true,
    };
    let dl = Instant::now() + deadline;
    let mut done_child = false;
    let mut out: Option<(Vec<u8>, u64)> = None;
    loop {
        if !done_child {
            if let Some(c) = guard.child.as_mut() {
                match c.try_wait() {
                    Ok(Some(_)) => {
                        done_child = true;
                    }
                    Ok(None) => {}
                    Err(_) => {
                        done_child = true;
                    }
                }
            } else {
                done_child = true;
            }
        }
        if out.is_none() {
            if let Ok(v) = rx.try_recv() {
                out = Some(v);
            }
        }
        if done_child && out.is_some() {
            guard.armed = false;
            let _ = guard.child.take();
            if let Some(h) = guard.handle.take() {
                let _ = h.join();
            }
            let (head, total) = out.unwrap();
            let trunc = total > head_limit as u64;
            return Ok(CaptureResult::new(head, total, trunc));
        }
        if !done_child && Instant::now() >= dl {
            shutdown_group(pid);
            if let Some(mut c) = guard.child.take() {
                let _ = c.wait();
            }
            if let Some(h) = guard.handle.take() {
                let _ = h.join();
            }
            guard.armed = false;
            return Err(CaptureError::Deadline);
        }
        tiny_sleep(Duration::from_millis(5)).await;
    }
}

