}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");
    let target_line = format!("applied:{key}");
    let target_bytes = format!("applied:{key}\n");
    let _ = std::fs::create_dir_all(&effect_dir);
    let already: bool = match std::fs::read(&log_path) {
        Ok(data) => {
            let want = target_line.as_bytes();
            data.split(|&b| b == b'\n').any(|mut line| {
                if line.last() == Some(&b'\r') {
                    line = &line[..line.len() - 1];
                }
                line == want
            })
        }
        Err(_) => false,
    };
    let did_append = !already;
    if did_append {
        use std::io::Write as _;
        let mut f = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
            .expect("open applied.log");
        f.write_all(target_bytes.as_bytes())
            .expect("append applied.log");
        let _ = f.sync_all();
    }
    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline
            .checked_sub(start.elapsed())
            .unwrap_or(std::time::Duration::ZERO);
        let wait = std::cmp::min(remaining, std::time::Duration::from_millis(5));
        if !wait.is_zero() {
            std::thread::sleep(wait);
        }
        std::future::poll_fn(|cx| {
            cx.waker().wake_by_ref();
            std::task::Poll::<()>::Pending
        })
        .await;
    }
    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

