pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let target_line = format!("applied:{}", key);
    let target_bytes = format!("applied:{}\n", key);
    let applied_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    let _ = std::fs::create_dir_all(&effect_dir);

    let already: bool = match std::fs::read_to_string(&applied_path) {
        Ok(content) => content.lines().any(|l| l == target_line),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => {
            let _ = std::fs::create_dir_all(&effect_dir);
            match std::fs::read_to_string(&applied_path) {
                Ok(content) => content.lines().any(|l| l == target_line),
                Err(_) => false,
            }
        }
    };

    let did_append: bool = if already {
        false
    } else {
        let mut file = match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&applied_path)
        {
            Ok(f) => f,
            Err(_) => {
                let _ = std::fs::create_dir_all(&effect_dir);
                match std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(&applied_path)
                {
                    Ok(f) => f,
                    Err(_) => {
                        std::thread::sleep(Duration::from_millis(10));
                        let _ = std::fs::create_dir_all(&effect_dir);
                        std::fs::OpenOptions::new()
                            .create(true)
                            .append(true)
                            .open(&applied_path)
                            .expect("unable to open applied.log")
                    }
                }
            }
        };
        match file.write_all(target_bytes.as_bytes()) {
            Ok(()) => {}
            Err(_) => {
                let present = std::fs::read_to_string(&applied_path)
                    .map(|c| c.lines().any(|l| l == target_line))
                    .unwrap_or(false);
                if !present {
                    let _ = file.write_all(target_bytes.as_bytes());
                }
            }
        }
        let _ = file.flush();
        let _ = file.sync_all();
        drop(file);
        let present = std::fs::read_to_string(&applied_path)
            .map(|c| c.lines().any(|l| l == target_line))
            .unwrap_or(false);
        if !present {
            if let Ok(mut f2) = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&applied_path)
            {
                let _ = f2.write_all(target_bytes.as_bytes());
                let _ = f2.flush();
                let _ = f2.sync_all();
            }
        }
        true
    };

    let start = Instant::now();
    let poll_interval = Duration::from_millis(5);
    loop {
        if release_path.exists() {
            break;
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let elapsed = start.elapsed();
        let remaining = deadline.checked_sub(elapsed).unwrap_or(Duration::ZERO);
        if remaining.is_zero() {
            if release_path.exists() {
                break;
            }
            return Err(RecoverError::Deadline);
        }
        let sleep_for = if poll_interval < remaining {
            poll_interval
        } else {
            remaining
        };
        sleep_async(sleep_for).await;
    }

    if did_append {
        Ok(format!("applied:{}", key))
    } else {
        Ok(format!("recovered:{}", key))
    }
}

async fn sleep_async(dur: Duration) {
    if dur.is_zero() {
        return;
    }
    let end = Instant::now()
        .checked_add(dur)
        .unwrap_or_else(|| Instant::now() + Duration::from_secs(86400 * 365 * 10));
    std::future::poll_fn(move |cx: &mut std::task::Context<'_>| {
        if Instant::now() >= end {
            std::task::Poll::Ready(())
        } else {
            let w = cx.waker().clone();
            let rem = end.saturating_duration_since(Instant::now());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                w.wake();
            });
            std::task::Poll::Pending
        }
    })
    .await
}

