                            head.extend_from_slice(&buf[..take]);
                        }
                    }
                    Err(e)
                        if e.kind() == std::io::ErrorKind::Interrupted =>
                    {
                        continue
                    }
                    Err(_) => break,
                }
            }
            let _ = tx.send((head, total));
        })),
        None => {
            drop(tx);
            None
        }
    };
    let mut guard = Guard {
        child: Some(child),
        pid,
        reader,
        done: false,
    };
    let pid_copy = guard.pid;
    let mut output: Option<(Vec<u8>, u64)> = None;
    let mut child_done = false;
    let mut reader_done = false;
    let mut deadline_fired = false;
    let mut success_kill_sent = false;
    loop {
        if !reader_done {
            match rx.try_recv() {
                Ok(v) => {
                    output = Some(v);
                    reader_done = true;
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    reader_done = true;
                    if output.is_none() {
                        output = Some((Vec::new(), 0));
                    }
                }
            }
        }
        if !child_done {
            if let Some(c) = guard.child.as_mut() {
                match c.try_wait() {
                    Ok(Some(_)) => {
                        child_done = true;
                    }
                    Ok(None) => {}
                    Err(_) => {
                        child_done = true;
                    }
                }
            } else {
                child_done = true;
            }
        }
        if child_done && reader_done {
            break;
        }
        if !child_done && !deadline_fired && start.elapsed() >= deadline {
            deadline_fired = true;
            kill_group(pid_copy);
            if let Some(c) = guard.child.as_mut() {
                let _ = c.kill();
            }
        }
        if child_done && !reader_done && !deadline_fired && !success_kill_sent {
            success_kill_sent = true;
            kill_group(pid_copy);
        }
        std::future::poll_fn(|cx| {
            let w = cx.waker().clone();
            std::thread::spawn(move || {
                std::thread::sleep(std::time::Duration::from_millis(2));
                w.wake();
            });
            std::task::Poll::Pending::<()>
        })
        .await;
    }
    if deadline_fired {
        guard.done = true;
        return Err(CaptureError::Deadline);
    } else {
        let (h, t) = output.unwrap_or((Vec::new(), 0));
        let trunc = t > head_limit as u64;
        guard.done = true;
        return Ok(CaptureResult::new(h, t, trunc));
    }
}

