pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: std::time::Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }
    let mut cmd = Command::new(&argv[0]);
    for a in argv.iter().skip(1) {
        cmd.arg(a);
    }
    cmd.stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    #[cfg(unix)]
    {
        cmd.process_group(0);
    }
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };
    let pgid = child.id();
    let stdout = match child.stdout.take() {
        Some(s) => s,
        None => {
            kill_pg(pgid);
            let _ = child.kill();
            let _ = child.wait();
            return Err(CaptureError::Cancelled);
        }
    };
    let (tx, rx) = std::sync::mpsc::channel::<(u64, Vec<u8>)>();
    let _ = std::thread::spawn(move || {
        reader_fn(stdout, head_limit, tx);
    });
    let mut guard = Guard {
        child: Some(child),
        pgid,
    };
    let start = Instant::now();
    let mut cached: Option<(u64, Vec<u8>)> = None;
    loop {
        if cached.is_none() {
            match rx.try_recv() {
                Ok(v) => {
                    cached = Some(v);
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
                Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                    kill_pg(pgid);
                    if let Some(mut c) = guard.child.take() {
                        let _ = c.kill();
                        let _ = c.wait();
                    }
                    return Err(CaptureError::Cancelled);
                }
            }
        }
        if start.elapsed() >= deadline {
            kill_pg(pgid);
            if let Some(mut c) = guard.child.take() {
                let _ = c.kill();
                let _ = c.wait();
            }
            return Err(CaptureError::Deadline);
        }
        let exited = match guard.child.as_mut() {
            Some(c) => match c.try_wait() {
                Ok(Some(_)) => true,
                Ok(None) => false,
                Err(_) => false,
            },
            None => false,
        };
        if exited {
            kill_pg(pgid);
            let (total, head) = if let Some(v) = cached.take() {
                v
            } else {
                let mut got: Option<(u64, Vec<u8>)> = None;
                loop {
                    match rx.try_recv() {
                        Ok(v) => {
                            got = Some(v);
                            break;
                        }
                        Err(std::sync::mpsc::TryRecvError::Empty) => {
                            sleep_async(Duration::from_millis(1)).await;
                        }
                        Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                            kill_pg(pgid);
                            guard.child.take();
                            return Err(CaptureError::Cancelled);
                        }
                    }
                }
                match got {
                    Some(v) => v,
                    None => {
                        guard.child.take();
                        return Err(CaptureError::Cancelled);
                    }
                }
            };
            guard.child.take();
            let mut head = head;
            if head.len() > head_limit {
                head.truncate(head_limit);
            }
            let truncated = total > head_limit as u64;
            return Ok(CaptureResult::new(head, total, truncated));
        }
        sleep_async(Duration::from_millis(5)).await;
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let _ = std::fs::create_dir_all(&effect_dir);
    let log_path = effect_dir.join("applied.log");
    let target = format!("applied:{key}");
    let line = format!("applied:{key}\n");
    let target_bytes = target.as_bytes();

    let already_present: bool = match std::fs::read(&log_path) {
        Ok(bytes) => {
            let mut found = false;
            for part in bytes.split(|&b| b == b'\n') {
                let p = if !part.is_empty() && part[part.len() - 1] == b'\r' {
                    &part[..part.len() - 1]
                } else {
                    part
                };
                if p == target_bytes {
                    found = true;
                    break;
                }
            }
            found
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => false,
    };

    let did_append = !already_present;
    if did_append {
        match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(&log_path)
        {
            Ok(mut f) => {
                {
                    use std::io::Write;
                    if f.write_all(line.as_bytes()).is_err() {
                        return Err(RecoverError::Deadline);
                    }
                }
                let _ = f.sync_all();
            }
            Err(_) => {
                return Err(RecoverError::Deadline);
            }
        }
    }

    let release_path = effect_dir.join("release");
    let start = std::time::Instant::now();
    loop {
        if std::fs::symlink_metadata(&release_path).is_ok() {
            break;
        }
        if start.elapsed() >= deadline {
            if std::fs::symlink_metadata(&release_path).is_ok() {
                break;
            }
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(start.elapsed());
        if remaining.is_zero() {
            if std::fs::symlink_metadata(&release_path).is_ok() {
                break;
            }
            return Err(RecoverError::Deadline);
        }
        let wait = std::cmp::min(remaining, std::time::Duration::from_millis(10));
        sleep_interval(wait).await;
    }

    if did_append {
        Ok(format!("applied:{key}"))
    } else {
        Ok(format!("recovered:{key}"))
    }
}

async fn sleep_interval(dur: std::time::Duration) {
    use std::future::poll_fn;
    use std::task::Poll;
    let start = std::time::Instant::now();
    poll_fn(|cx| {
        if start.elapsed() >= dur {
            Poll::Ready(())
        } else {
            let w = cx.waker().clone();
            let rem = dur.saturating_sub(start.elapsed());
            std::thread::spawn(move || {
                std::thread::sleep(rem);
                w.wake();
            });
            Poll::Pending
        }
    })
    .await
}

#[derive(Debug, PartialEq, Eq)]
pub enum RecoverError {
    Unknown,
    Deadline,
}

async fn sleep_async(dur: std::time::Duration) {
    if dur.is_zero() {
        return;
    }
    std::thread::sleep(dur);
}

pub async fn solve(
    effect_dir: std::path::PathBuf,
    key: String,
    deadline: std::time::Duration,
) -> Result<String, RecoverError> {
    let target = format!("applied:{key}");
    let log_path = effect_dir.join("applied.log");
    let release_path = effect_dir.join("release");

    // Synchronous check-and-append with no await in between, so a dropped
    // future cannot interleave here and SIGKILL sees a consistent state.
    let did_append: bool = {
        let _ = std::fs::create_dir_all(&effect_dir);
        let already: bool = match std::fs::read_to_string(&log_path) {
            Ok(content) => content.lines().any(|l| l == target),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
            Err(_) => false,
        };
        if already {
            false
        } else {
            use std::io::Write;
            match std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(&log_path)
            {
                Ok(mut f) => {
                    let line = format!("{target}\n");
                    let _ = f.write_all(line.as_bytes());
                    let _ = f.sync_all();
                    match std::fs::read_to_string(&log_path) {
                        Ok(content) if content.lines().any(|l| l == target) => true,
                        _ => true,
                    }
                }
                Err(_) => false,
            }
        }
    };

    let start = std::time::Instant::now();
    loop {
        if release_path.exists() {
            if did_append {
                return Ok(format!("applied:{key}"));
            } else {
                return Ok(format!("recovered:{key}"));
            }
        }
        if start.elapsed() >= deadline {
            return Err(RecoverError::Deadline);
        }
        let remaining = deadline.saturating_sub(start.elapsed());
        let step = std::time::Duration::from_millis(5).min(remaining);
        if step.is_zero() {
            return Err(RecoverError::Deadline);
        }
        sleep_async(step).await;
    }
}

